#!/usr/bin/env python3

# USAGE
#   Run fslFoam with outputStreamLines on, then run foamToVTK for the mesh:
#   ./vizStreamLines.py "/path/to/case" xy
#
# REQUIREMENTS
# - Determine the latest timestep for the selected case mesh.
# - Read the mesh surface names from the vizStreamLines section of
#   utils/utilConfig.json and display the matching surfaces for that timestep.
# - Display the flow trajectories generated by fslFoam from
#   postProcessing/tracks.vtk; do not generate a second set from inlet faces.
# - Color each displayed streamline by its age-derived time of flight.
# - Display the configured mesh surface edges in the requested coordinate-plane
#   view, or isometric when no plane is specified.
# - Save the image as <case_name>.png in the current working directory.

import argparse
import json
from pathlib import Path
import sys

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from utils.vtkTrajectories import add_trajectories

import numpy as np
import pyvista as pv

parser = argparse.ArgumentParser()
parser.add_argument(
    "case",
    nargs="?",
    help="case directory or case name (defaults to the current directory)",
)
parser.add_argument(
    "plane",
    nargs="?",
    type=str.lower,
    choices=("xz", "yz", "xy", "yx", "zy", "zx"),
    help="coordinate plane to view (defaults to isometric)",
)
args = parser.parse_args()

config_file = Path(__file__).with_name("utilConfig.json")
try:
    with config_file.open(encoding="utf-8") as file:
        util_config = json.load(file)
except (OSError, UnicodeError, json.JSONDecodeError) as error:
    parser.error(f"could not read utility configuration {config_file}: {error}")

viz_config = (
    util_config.get("vizStreamLines") if isinstance(util_config, dict) else None
)
if not isinstance(viz_config, dict):
    parser.error(f"missing vizStreamLines section in {config_file}")
surfaces = viz_config.get("surfaces")
if (
    not isinstance(surfaces, list)
    or not surfaces
    or any(
        not isinstance(surface, str)
        or not surface.strip()
        or Path(surface).name != surface
        or surface in (".", "..")
        for surface in surfaces
    )
    or len(set(surfaces)) != len(surfaces)
):
    parser.error(
        f"{config_file}: vizStreamLines.surfaces must be a non-empty list "
        "of unique surface names"
    )

if args.case is None:
    case_dir = Path.cwd()
    case_name = case_dir.name
else:
    case_path = Path(args.case).expanduser()
    if case_path.is_dir():
        case_dir = case_path.resolve()
        case_name = case_dir.name
    elif case_path.is_absolute() or len(case_path.parts) > 1:
        parser.error(f"case directory does not exist: {case_path}")
    else:
        case_dir = Path.cwd()
        case_name = args.case

vtk_dir = case_dir / "VTK"
if not vtk_dir.is_dir():
    parser.error(f"VTK directory not found for case {case_name!r}: {vtk_dir}")

vtk_files = (
    path
    for path in vtk_dir.glob(f"{case_name}_*.vtk")
    if path.stem.rsplit("_", 1)[-1].isdigit()
)
latest_vtk = max(
    vtk_files,
    key=lambda path: int(path.stem.rsplit("_", 1)[-1]),
    default=None,
)
if latest_vtk is None:
    parser.error(f"no VTK timestep files found for case {case_name!r}")

latest_time = latest_vtk.stem.rsplit("_", 1)[-1]
surface_meshes = []
for surface in surfaces:
    surface_file = vtk_dir / surface / f"{surface}_{latest_time}.vtk"
    if not surface_file.is_file():
        print(
            f"[WARNING] Configured mesh surface '{surface}' not found for "
            f"timestep {latest_time}: {surface_file}. Skipping."
        )
        continue
    surface_meshes.append((surface, pv.read(surface_file)))
if not surface_meshes:
    parser.error(
        f"none of the configured mesh surfaces were found for timestep "
        f"{latest_time} in {vtk_dir}"
    )

flow_tracks_file = case_dir / "postProcessing" / "tracks.vtk"
if not flow_tracks_file.is_file():
    parser.error(
        f"fslFoam streamline output not found: {flow_tracks_file}; "
        "run fslFoam with outputStreamLines on"
    )
flow_tracks = pv.read(flow_tracks_file)
if flow_tracks.n_points == 0 or flow_tracks.n_lines == 0:
    parser.error(f"fslFoam streamline output contains no lines: {flow_tracks_file}")
if "age" not in flow_tracks.point_data:
    parser.error(f"fslFoam streamline output has no age data: {flow_tracks_file}")

ages = flow_tracks.point_data["age"]
time_of_flight = np.array(
    [
        ages[flow_tracks.get_cell(line_id).point_ids[-1]]
        - ages[flow_tracks.get_cell(line_id).point_ids[0]]
        for line_id in range(flow_tracks.n_lines)
    ]
)
flow_tracks.cell_data["TimeOfFlight"] = time_of_flight

pv.OFF_SCREEN = True

p = pv.Plotter(off_screen=True)
for surface, surface_mesh in surface_meshes:
    p.add_mesh(
        surface_mesh,
        name=surface,
        color="white",
        show_edges=True,
        edge_color="black",
        line_width=1,
        opacity=0.25,
    )
p.add_mesh(
    flow_tracks,
    scalars="TimeOfFlight",
    cmap="viridis",
    line_width=3,
    render_lines_as_tubes=True,
    scalar_bar_args={"title": "Time of flight (s)"},
)
add_trajectories(
    p,
    case_dir / "postProcessing" / "zermelo-no-flow.vtk",
    color="blue",
)

plane_orientation = {
    "xy": ((0, 0, 1), (0, 1, 0)),
    "yx": ((0, 0, -1), (1, 0, 0)),
    "xz": ((0, -1, 0), (0, 0, 1)),
    "zx": ((0, 1, 0), (1, 0, 0)),
    "yz": ((1, 0, 0), (0, 0, 1)),
    "zy": ((-1, 0, 0), (0, 1, 0)),
}
if args.plane is None:
    p.view_isometric()
else:
    view_direction, view_up = plane_orientation[args.plane]
    p.view_vector(view_direction, viewup=view_up)
p.reset_camera()
p.screenshot(f"{case_name}.png")
